// Package ssh implements an ssh-agent.
package ssh

import (
	"bytes"
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"

	"github.com/smlx/piv-agent/internal/keyservice/piv"
	"github.com/smlx/piv-agent/internal/notify"
	pinentry "github.com/smlx/piv-agent/internal/pinentry"
